function [RawData] = LoadNetCDF(day,month,year,Path)
    % This function loads the netCDF file for the input date

    % inputs
    % day   = double in d or dd form
    % month = double in m or mm form
    % year  = double in yyyy form
    % Path = structure containing the file paths

    % outputs
    % RawData - structure containing the following fields
    % RawData.MCS - data generated by the MCS (The photon counts) 
    % RawData.HKeep - data generated by the thermistors
    % RawData.Container - data generated by the LabVIEW program collecting
    % instances of other objects

    % store the current folder as a temporary variable
    home = pwd;
    
    % turn the day, month, and year variables into a string to open the
    % folder containing the raw data
    foldername = string(year);

    if month >= 10
        foldername = strcat(foldername,num2str(month));
    else
        foldername = strcat(foldername,"0",num2str(month));
    end

    if day >= 10
        foldername = strcat(foldername,num2str(day));
    else
        foldername = strcat(foldername,"0",num2str(day));
    end

    % clear the unnecessary variables
    clear day month year

    % call functions to load the RawData
    [RawData.MCS]       = LoadMCS(foldername,Path);
    [RawData.Container] = LoadContainer(foldername,Path);
    [RawData.HKeep] = LoadHousekeeping(foldername,Path);
    
    % navigate back to the original folder
    cd(home)

    
end